"""Browser DOM acceptance with mocked storage/worker, not real PWA tests."""
from pathlib import Path
from base64 import b64encode
import json,os
from playwright.sync_api import sync_playwright
site=Path(__file__).resolve().parents[1]/'site'
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH') or None,args=['--no-sandbox','--disable-dev-shm-usage']);page=b.new_page(viewport={'width':390,'height':844},is_mobile=True,has_touch=True,reduced_motion='reduce');errors=[];page.set_default_timeout(5000);page.on('pageerror',lambda e:errors.append(str(e)))
 def mock(values):return '<script>window.xiStore='+json.dumps(values)+';Object.defineProperty(window,"localStorage",{configurable:true,value:{getItem(k){return xiStore[k]??null},setItem(k,v){xiStore[k]=String(v)},removeItem(k){delete xiStore[k]}}});</script>'
 def game(id,values):page.set_content((site/f'games/{id}/index.html').read_text().replace('<script>',mock(values)+'<script>',1))
 def unlock():
  page.get_by_role('button',name='?',exact=True).click();page.locator('#xi-private-pin').fill('000000');page.get_by_role('button',name='Mở khóa',exact=True).click();assert page.get_by_text('Mã PIN không đúng.').is_visible();assert page.locator('#xi-private-dialog input[type=number]').count()==0;page.locator('#xi-private-pin').fill('040804');page.get_by_role('button',name='Mở khóa',exact=True).click()
 game('cubiq',{});page.locator('[data-act=menu]').click();unlock();page.locator('#xi-private-unlocked').fill('50');page.locator('#xi-private-jump').fill('25');page.locator('#xi-private-assist').fill('1');page.get_by_role('button',name='Áp dụng').click();assert page.locator('[data-el=level]').inner_text()=='Màn 25';assert page.locator('[data-el=hearts]').inner_text()=='∞';s=page.evaluate('xiStore');d=json.loads(s['xi:game:cubiq:save']);assert d['level']==25 and d['unlocked']==50 and d['assist'] is True;page.locator('[data-act=menu]').click();page.get_by_role('button',name='?',exact=True).click();assert page.locator('#xi-private-pin').is_visible();page.get_by_role('button',name='Đóng',exact=True).click();print('PASS CUBIQ PIN, jump, unlock, infinite lives and re-lock')
 game('block-nova',s);page.locator('#settings').click();unlock();page.locator('#xi-private-score').fill('25000');page.locator('#xi-private-best').fill('500000');page.get_by_role('button',name='Áp dụng').click();s=page.evaluate('xiStore');assert json.loads(s['xi:game:block-nova:classic'])['score']==25000;assert json.loads(s['xi:game:block-nova:best'])==500000;assert json.loads(s['xi:game:cubiq:save'])['level']==25;print('PASS BLOCK NOVA custom score, independent save')
 game('feather-fury',s);page.locator('#menu').click();page.get_by_role('button',name='Cài đặt',exact=True).click();unlock();page.locator('#xi-private-coins').fill('90000');page.locator('#xi-private-feathers').fill('800');page.get_by_role('button',name='Áp dụng').click();s=page.evaluate('xiStore');d=json.loads(s['xi:game:feather-fury:ff10-progress']);assert d['coins']==90000 and d['feathers']==800;print('PASS FEATHER FURY local wallet')
 html=(site/'index.html').read_text().replace('<link rel="stylesheet" href="hub.css">','<style>'+(site/'hub.css').read_text()+'</style>').replace('src="assets/icon-192.png"','src="data:image/png;base64,'+b64encode((site/'assets/icon-192.png').read_bytes()).decode()+'"');cat=(site/'catalog-data.js').read_text()
 for name in ['legacy','cubiq','block-nova','feather-fury']:
  path='assets/'+name+'-cover.'+('svg' if name=='feather-fury' else 'webp');cat=cat.replace(path,'data:'+('image/svg+xml' if name=='feather-fury' else 'image/webp')+';base64,'+b64encode((site/path).read_bytes()).decode())
 js=(site/'hub.js').read_text().replace("import {games,released,HUB_VERSION,getGame} from './catalog.js';","const {games,released,HUB_VERSION,getGame}=globalThis.XI_CATALOG;")
 worker="Object.defineProperty(navigator,'serviceWorker',{configurable:true,value:{getRegistration:async()=>({active:{postMessage(m,p){p[0].postMessage({ok:true,value:{}})}}}),register:async()=>({}),ready:Promise.resolve(),addEventListener(){}}});"
 def hub(values):page.set_content(html.replace('<script type="module" src="hub.js"></script>',mock(values)+'<script>'+worker+cat+js+'</script>'))
 hub(s);page.get_by_role('button',name='Cài đặt',exact=True).click();assert page.locator('#themeChoices button').count()==6
 for key in ['jade','midnight','amethyst','ember','pearl','autumn']:
  page.locator(f'#themeChoices [data-theme={key}]').click();assert page.locator('html').get_attribute('data-theme')==key;assert page.evaluate('document.documentElement.scrollWidth<=innerWidth')
 page.locator('#themeChoices [data-theme=midnight]').click();page.locator('#compactCards').check();# valid PNG generated in browser
 buf=page.evaluate("(()=>{let c=document.createElement('canvas');c.width=64;c.height=48;let x=c.getContext('2d');x.fillStyle='#70a2cb';x.fillRect(0,0,64,48);return c.toDataURL('image/png').split(',')[1]})()")
 import base64
 page.locator('#wallpaperFile').set_input_files({'name':'wall.png','mimeType':'image/png','buffer':base64.b64decode(buf)});page.get_by_text('Đã lưu ảnh nền trên thiết bị.').wait_for();assert page.locator('html').get_attribute('data-wallpaper')=='true';stored=page.evaluate('xiStore');assert json.loads(stored['xi:ui:appearance-v1'])=={'theme':'midnight','compact':True};assert stored['xi:ui:wallpaper-v1'].startswith('data:image/jpeg;');page.screenshot(path=str(site.parent/'appearance-preview.png'),full_page=True)
 page.get_by_role('button',name='Khám phá',exact=True).click();page.locator('#gameSearch').fill('CUBIQ');assert page.locator('#featured article').count()==1;page.locator('#gameSearch').fill('notfound');assert page.locator('#noGames').is_visible();page.locator('#gameSearch').fill('');assert page.locator('#featured article').count()==4;page.screenshot(path=str(site.parent/'midnight-compact-preview.png'),full_page=True)
 page.close();page=b.new_page(viewport={'width':390,'height':844},is_mobile=True,has_touch=True,reduced_motion='reduce');page.set_default_timeout(5000);page.on('pageerror',lambda e:errors.append(str(e)));hub(stored);assert page.locator('html').get_attribute('data-theme')=='midnight';assert page.locator('html').get_attribute('data-wallpaper')=='true';page.get_by_role('button',name='Cài đặt',exact=True).click();page.locator('#appearanceReset').click();assert page.locator('html').get_attribute('data-theme')=='autumn';assert page.locator('html').get_attribute('data-wallpaper')=='false';assert page.evaluate('xiStore["xi:game:cubiq:save"]')==stored['xi:game:cubiq:save'];print('PASS six themes, image upload, compact layout, search, persistent preferences, reset without game save changes');assert not errors,errors;b.close()
